UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-carditek/cdk-222-ft.pdf',
  descripcion_larga_es = $d$Compresor nebulizador orientado a terapias respiratorias domiciliarias y clínicas, con generación de partículas finas para mejor depósito pulmonar. Diseño robusto para uso continuo en atención primaria y hogar.

