UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-nube/gmrn-211-ft.pdf',
  descripcion_larga_es = $d$El Compresor Nebulizador Nube 3000+ es una solución avanzada para tratamientos respiratorios, equipada con un micronebulizador de flujo graduable que permite ajustar la cantidad de medicamento, evitando desperdicios y garantizando una administración eficiente. Además, incluye un lavador nasal que facilita la limpieza de las vías respiratorias, proporcionando un tratamiento integral. Diseñado para uso continuo, es ideal tanto para el hogar como para entornos clínicos.

El compresor nebulizador Nube 3000+ incorpora un micronebulizador de flujo graduable que permite ajustar la cantidad de medicamento y evitar desperdicios, además de un lavador nasal para limpiar las vías respiratorias. Está diseñado para uso continuo en el hogar o en entornos clínicos, mide 9,5 x 17 x 15 cm, pesa 1,4 kg y tiene garantía de 5 años o 2000 horas.$d$,
  descripcion_larga_en = $d$The Nube 3000+ Nebulizer Compressor is an advanced solution for respiratory treatments, equipped with a variable-flow micronebulizer that allows adjusting the amount of medication, avoiding waste and ensuring efficient administration. Additionally, it includes a nasal washer that facilitates airway cleaning, providing comprehensive treatment. Designed for continuous use, it is ideal for both home and clinical settings.

The Nube 3000+ nebulizer compressor includes an adjustable-flow micronebulizer that lets you adjust the amount of medication and avoid waste, plus a nasal washer to clean the airways. It is designed for continuous use at home or in clinical settings, measures 9.5 x 17 x 15 cm, weighs 1.4 kg and has a 5-year or 2000-hour warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"GMD (Colombia)"},{"clave":"Referencia","grupo":"Identificación","valor":"GMRN-211 (Nube 3000+)"},{"clave":"Tamaño / peso","grupo":"Dimensiones","valor":"9,5 x 17 x 15 cm; 1,4 kg"},{"clave":"Garantía","grupo":"Garantía","valor":"5 años o 2000 h"},{"clave":"Temperatura / humedad","grupo":"Ambiente","valor":"-20 a 70 °C / 10 a 95 %"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Micronebulizador de flujo graduable para ajustar la dosis y evitar desperdicio.","Lavador nasal incluido para un tratamiento más completo.","Uso continuo en casa o entornos clínicos; garantía de 5 años o 2000 horas."],"beneficios_en":["Adjustable-flow micronebulizer to adjust the dose and avoid waste.","Nasal washer included for a more complete treatment.","Continuous use at home or clinical settings; 5-year or 2000-hour warranty."],"valor_es":"Un compresor nebulizador colombiano para terapia respiratoria en casa o en entornos clínicos, con ficha técnica oficial descargable.","valor_en":"A Colombian nebulizer compressor for respiratory therapy at home or in clinical settings, with an official downloadable datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué incluye el kit?","a":"Micronebulizador, línea neumática y los demás accesorios listados en la ficha técnica descargable."},{"q":"¿Cuánto pesa?","a":"1,4 kg, con 9,5 x 17 x 15 cm."},{"q":"¿Qué garantía tiene?","a":"5 años o 2000 horas de uso."},{"q":"¿Dónde descargo la ficha técnica de Compresor Nebulizador Nube 3000+?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Nube) (en español)."}],"preguntas_frecuentes_en":[{"q":"What does the kit include?","a":"Micronebulizer, pneumatic line and the other accessories listed in the downloadable datasheet."},{"q":"How much does it weigh?","a":"1.4 kg, at 9.5 x 17 x 15 cm."},{"q":"What warranty does it have?","a":"5 years or 2000 hours of use."},{"q":"Where can I download the Nube 3000+ Nebulizer Compressor datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Nube) PDF (in Spanish)."}],"seo_keywords_es":["nebulizador Nube 3000+","compresor nebulizador con lavador nasal","micronebulizador de flujo graduable","nebulizador GMR","nebulizador Colombia","ficha técnica GMRN-211"],"seo_keywords_en":["Nube 3000+ nebulizer","nebulizer compressor with nasal washer","adjustable-flow micronebulizer","GMR nebulizer","nebulizer Colombia","GMRN-211 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Nube)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCBQYS2S56VNAPFJSO73HVY5GCGI?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'compresor-nebulizador-nube-3000-plus-ref-gmrn-211';

