me nebulizer","GMR nebulizer","nebulizer Colombia","GMRN457-12 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Nube)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCRXLEOBIYXFCDPM3Q6LDSDWZXMI?version=2.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
