onitor","rechargeable blood pressure monitor","blood pressure monitor Colombia","CDK-BPM-66EP datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Carditek)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC4HBC3V3SF5CJ3GSJKJR65FE5DI?version=2.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
