  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Todo en un paquete: glucómetro, 50 tirillas y 100 lancetas.","Resultado en 5 segundos con 0,8 µL y memoria de 512 mediciones.","Glucómetro con 5 años de garantía y ficha técnica oficial."],"beneficios_en":["All in one package: glucometer, 50 strips and 100 lancets.","Result in 5 seconds with 0.8 µL and 512-measurement memory.","Glucometer with 5-year warranty and official datasheet."],"valor_es":"Un kit de inicio para empezar a controlar la glucosa en casa, con documentación oficial de Latidos.","valor_en":"A starter kit to begin controlling glucose at home, with official Latidos documentation.","preguntas_frecuentes_es":[{"q":"¿Qué incluye el kit?","a":"Glucómetro LTD-B10, 50 tirillas reactivas y 100 lancetas estériles."},{"q":"¿Qué rango mide el glucómetro?","a":"De 20 a 600 mg/dL."},{"q":"¿Cuánto tarda la medición?","a":"5 segundos."},{"q":"¿Dónde descargo la ficha técnica de Kit de Glucometría Basic Latidos?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Latidos) (en español)."}],"preguntas_frecuentes_en":[{"q":"What does the kit include?","a":"LTD-B10 glucometer, 50 test strips and 100 sterile lancets."},{"q":"What range does the glucometer measure?","a":"From 20 to 600 mg/dL."},{"q":"How long does a measurement take?","a":"5 seconds."},{"q":"Where can I download the Latidos Glucose Monitoring Kit datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Latidos) PDF (in Spanish)."}],"seo_keywords_es":["kit de glucometría Latidos","kit de glucómetro con tirillas y lancetas","glucómetro LTD-B10 kit","monitoreo de glucosa en casa","glucómetro Colombia","ficha técnica LTD-B10-K"],"seo_keywords_en":["Latidos glucometry kit","glucometer kit with strips and lancets","LTD-B10 kit","home glucose monitoring","glucometer Colombia","LTD-B10-K datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Latidos)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCBRKCUGNIDRFEVEKMXS2NQPOHBI?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
