UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-latidos/ltd-b10-l-ft.pdf',
  descripcion_larga_es = $d$Las Lancetas para glucómetros Latidos, son dispositivos de un solo uso diseñados para obtener muestras de sangre capilar de manera segura, indolora y eficiente. Fabricadas con una aguja de acero inoxidable de alta calidad y un cuerpo de policloruro de vinilo (PVC), garantizan una punción precisa y mínima molestia para el usuario. Su
método de esterilización por irradiación asegura un uso higiénico y seguro

Las lancetas Latidos LTD-B10-L (caja de 50) son dispositivos de un solo uso para obtener sangre capilar de forma segura y con mínima molestia, con aguja de acero inoxidable y cuerpo de PVC de 32 x 6,4 mm. Se esterilizan por irradiación, con vigencia de la esterilización de 5 años, y tienen registro sanitario 2024DM-0029569 (clase IIA).$d$,
  descripcion_larga_en = $d$Latidos glucometer lancets are single-use devices designed to obtain capillary blood samples safely, painlessly and efficiently. Made with high-quality stainless steel needles and polyvinyl chloride (PVC) body, they ensure precise puncture and minimal discomfort for the user. Their irradiation sterilization method ensures hygienic and safe use.

The Latidos LTD-B10-L lancets (box of 50) are single-use devices to obtain capillary blood safely and with minimal discomfort, with a stainless-steel needle and a 32 x 6.4 mm PVC body. They are sterilised by irradiation, with a sterilisation validity of 5 years, and have health registration 2024DM-0029569 (class IIA).$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"GMD (Colombia)"},{"clave":"Referencia","grupo":"Identificación","valor":"LTD-B10-L"},{"clave":"Tamaño","grupo":"Dimensiones","valor":"32 x 6,4 mm"},{"clave":"Aguja / cuerpo","grupo":"Material","valor":"Acero inoxidable / PVC"},{"clave":"Método","grupo":"Esterilización","valor":"Irradiación; vigencia 5 años"},{"clave":"Registro sanitario","grupo":"Regulatorio","valor":"2024DM-0029569; clase IIA"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aguja de acero inoxidable de alta calidad para una punción precisa.","Un solo uso y esterilización por irradiación con 5 años de vigencia.","Caja de 50 unidades con registro sanitario."],"beneficios_en":["High-quality stainless-steel needle for a precise puncture.","Single use and irradiation sterilisation with 5 years of validity.","Box of 50 units with health registration."],"valor_es":"Lancetas estériles de un solo uso para el glucómetro LTD-B10, con ficha oficial de Latidos.","valor_en":"Sterile single-use lancets for the LTD-B10 glucometer, with official Latidos datasheet.","preguntas_frecuentes_es":[{"q":"¿Cómo se esterilizan?","a":"Por irradiación; la vigencia de la esterilización es de 5 años."},{"q":"¿Son reutilizables?","a":"No, son dispositivos de un solo uso."},{"q":"¿Cuántas trae la caja?","a":"50 unidades."},{"q":"¿Dónde descargo la ficha técnica de Lancetas Para Glucómetros Latidos x 50 Unidades?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Latidos) (en español)."}],"preguntas_frecuentes_en":[{"q":"How are they sterilised?","a":"By irradiation; the sterilisation validity is 5 years."},{"q":"Are they reusable?","a":"No, they are single-use devices."},{"q":"How many are in the box?","a":"50 units."},{"q":"Where can I download the Lancets for Latidos Glucometer x 50 Units datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Latidos) PDF (in Spanish)."}],"seo_keywords_es":["lancetas Latidos","lancetas para glucómetro x 50","lancetas estériles de un solo uso","lancetas LTD-B10-L","insumos de glucometría Colombia","ficha técnica LTD-B10-L"],"seo_keywords_en":["Latidos lancets","glucometer lancets x 50","sterile single-use lancets","LTD-B10-L lancets","glucometry supplies Colombia","LTD-B10-L datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Latidos)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCNNSBKITSY5HIVHVEPNKDULZFDU?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
