UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/ltd-b10-tr-ft.pdf',
  descripcion_larga_es = $d$Las tiras reactivas de glucosa se utilizan como medidor de glucosa en sangre para
monitoreo Invitro de la concentración de glucosa en sangre entera capilar humano, que puede ser utilizada por profesionales, no profesionales en casa o en unidades médicas.  Este producto sólo se utiliza para monitorear la glucosa en pacientes diabéticos. No puede utilizarse para el diagnóstico de la diabetes ni como base para el ajuste de dosis de medicamentos terapéuticos.

Las tirillas reactivas Latidos LTD-B10-TR (50 unidades, cajas de 2 x 25) miden glucosa en sangre entera capilar humana con enzima GDH-FAD y 0,8 µL de muestra, con rango de 20 a 600 mg/dL. Sirven para el monitoreo in vitro de pacientes diabéticos por profesionales o personas en casa; no se usan para diagnosticar diabetes ni para ajustar dosis de medicamentos. Registro INVIMA 2024RD-0008800.$d$,
  descripcion_larga_en = $d$Glucose test strips are used for in vitro monitoring of whole human capillary blood glucose concentration, usable by professionals, non-professionals at home, or in medical units. This product is only used to monitor glucose in diabetic patients. It cannot be used for the diagnosis of diabetes or as a basis for adjusting doses of therapeutic medications.

The Latidos LTD-B10-TR test strips (50 units, boxes of 2 x 25) measure glucose in human capillary whole blood using GDH-FAD enzyme and a 0.8 µL sample, with a range of 20 to 600 mg/dL. They are for in vitro monitoring of diabetic patients by professionals or people at home; they are not used to diagnose diabetes or to adjust medication doses. INVIMA registration 2024RD-0008800.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"GMD (Colombia)"},{"clave":"Referencia","grupo":"Identificación","valor":"LTD-B10-TR"},{"clave":"Rango / muestra","grupo":"Medición","valor":"20 - 600 mg/dL / 0,8 µL"},{"clave":"Enzima","grupo":"Composición","valor":"GDH-FAD; 4 electrodos de plata"},{"clave":"Unidades","grupo":"Presentación","valor":"50 (2 x 25)"},{"clave":"Registro INVIMA","grupo":"Regulatorio","valor":"2024RD-0008800; tipo II"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Enzima GDH-FAD y 4 electrodos de plata con solo 0,8 µL de muestra.","Rango de 20 a 600 mg/dL compatible con el glucómetro LTD-B10.","Vigencia de 24 meses sin abrir y 6 meses tras abrir el vial."],"beneficios_en":["GDH-FAD enzyme and 4 silver electrodes with only 0.8 µL of sample.","20 to 600 mg/dL range compatible with the LTD-B10 glucometer.","24 months valid unopened and 6 months after opening the vial."],"valor_es":"Tirillas de glucosa para el glucómetro LTD-B10 con registro INVIMA y ficha oficial de Latidos.","valor_en":"Glucose test strips for the LTD-B10 glucometer with INVIMA registration and official Latidos datasheet.","preguntas_frecuentes_es":[{"q":"¿Con qué glucómetro se usan?","a":"Con el glucómetro Latidos de referencia LTD-B10."},{"q":"¿Sirven para diagnosticar diabetes?","a":"No: solo para monitorear la glucosa en pacientes diabéticos, no como base para ajustar dosis de medicamentos."},{"q":"¿Cómo se almacenan?","a":"A temperatura ambiente de 4 a 30 °C y humedad relativa de 20 a 80 %, sin congelar."},{"q":"¿Dónde descargo la ficha técnica de Tirillas Reactivas Para El Glucómetro LTD-B10 x 50 Unidades?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Which glucometer do they work with?","a":"The Latidos glucometer reference LTD-B10."},{"q":"Can they diagnose diabetes?","a":"No: only to monitor glucose in diabetic patients, not as a basis to adjust medication doses."},{"q":"How are they stored?","a":"At room temperature of 4 to 30 °C and relative humidity of 20 to 80%, without freezing."},{"q":"Where can I download the Test Strips for LTD-B10 Glucometer x 50 Units datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["tirillas reactivas para glucómetro","tirillas Latidos LTD-B10-TR","tiras de glucosa x 50","tirillas de glucosa Colombia","insumos de glucometría","ficha técnica LTD-B10-TR"],"seo_keywords_en":["glucometer test strips","Latidos LTD-B10-TR strips","glucose strips x 50","glucose strips Colombia","glucometry supplies","LTD-B10-TR datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCOOU5E7OWTZAURCR7YJSIH32ZKI?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'tirillas-reactivas-para-el-glucometro-ltd-b10-x-50-unidades-ref-ltd-b10-tr';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/gmr-sm181-ft.pdf',
  descripcion_larga_es = $d$El aspirador de secreciones ADS 100 es una unidad de succión portátil, diseñada para la eliminación efectiva de fluidos en las vías respiratorias y la extracción de material infeccioso de heridas. Su versatilidad permite su uso tanto en cirugías dentro de la sala de operaciones como en el cuidado postoperatorio en la habitación del paciente.

El aspirador de secreciones portátil ADS100 es una unidad de succión para eliminar fluidos de las vías respiratorias y material infeccioso de heridas, utilizable en quirófano o en la habitación del paciente, en adultos y niños. Genera presión de vacío de ≥ 0,07 MPa (525 mmHg), caudal ≥ 16 l/min y ruido ≤ 60 dB(A) a 1 m; funciona a 120 V (60 Hz), con válvula antidesborde y uso intermitente de máximo 30 minutos continuos. Tiene 3 años de garantía.$d$,
  descripcion_larga_en = $d$The ADS100 portable suction unit is designed for effective removal of fluids in the airways and extraction of infectious material from wounds. Its versatility allows use both in surgeries in the operating room and in post-operative care in the patient's room. Compact design facilitates transport and placement at different care points.

The ADS100 portable suction unit is used to remove fluids from the airways and infectious material from wounds, usable in the operating room or the patient's room, for adults and children. It generates vacuum pressure of ≥ 0.07 MPa (525 mmHg), flow ≥ 16 l/min and noise ≤ 60 dB(A) at 1 m; it runs at 120 V (60 Hz), with an overflow valve and intermittent use of up to 30 continuous minutes. It has a 3-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"GMD (Colombia)"},{"clave":"Referencia","grupo":"Identificación","valor":"GMR-SM181 (ADS100)"},{"clave":"Vacío máximo","grupo":"Rendimiento","valor":"≥ 0,07 MPa (525 mmHg)"},{"clave":"Caudal","grupo":"Rendimiento","valor":"≥ 16 l/min"},{"clave":"Ruido","grupo":"Acústica","valor":"≤ 60 dB(A) a 1 m"},{"clave":"Alimentación","grupo":"Eléctrico","valor":"120 V ±10 % AC, 60 Hz"},{"clave":"Ciclo","grupo":"Uso","valor":"Intermitente; máx. 30 min continuos"},{"clave":"Garantía","grupo":"Garantía","valor":"3 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Vacío de ≥ 0,07 MPa (525 mmHg) y caudal de ≥ 16 l/min.","Portátil, con válvula antidesborde, para uso hospitalario y doméstico.","Ruido ≤ 60 dB(A) a 1 metro y 3 años de garantía."],"beneficios_en":["Vacuum of ≥ 0.07 MPa (525 mmHg) and flow of ≥ 16 l/min.","Portable, with overflow valve, for hospital and home use.","Noise ≤ 60 dB(A) at 1 metre and 3-year warranty."],"valor_es":"Un aspirador de secreciones portátil con 525 mmHg de vacío para uso hospitalario y domiciliario, con ficha oficial.","valor_en":"A portable suction unit with 525 mmHg vacuum for hospital and home use, with official datasheet.","preguntas_frecuentes_es":[{"q":"¿Cuánto tiempo puede funcionar seguido?","a":"Es de uso intermitente, con un máximo de 30 minutos continuos."},{"q":"¿Qué rango de succión regula?","a":"De 0,02 a 0,07 MPa (150 a 525 mmHg)."},{"q":"¿Qué voltaje usa?","a":"120 V (±10 % AC), 60 Hz."},{"q":"¿Dónde descargo la ficha técnica de Aspirador De Secreciones Pórtatil ADS100?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How long can it run continuously?","a":"It is intermittent-duty, with a maximum of 30 continuous minutes."},{"q":"What suction range can be regulated?","a":"From 0.02 to 0.07 MPa (150 to 525 mmHg)."},{"q":"What voltage does it use?","a":"120 V (±10% AC), 60 Hz."},{"q":"Where can I download the Portable Secretions Aspirator ADS100 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["aspirador de secreciones portátil","aspirador ADS100","succión portátil","aspirador de secreciones Colombia","equipo de succión hospitalaria","ficha técnica GMR-SM181"],"seo_keywords_en":["portable suction unit","ADS100 aspirator","portable suction","secretion aspirator Colombia","hospital suction equipment","GMR-SM181 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCFKA4G6MKWNAONNRS5OOCBH6UJA?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'aspirador-de-secreciones-portatil-ads100-ref-gmr-sm181';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmr/gmr870-015-ft.pdf',
  descripcion_larga_es = $d$El Regulador para Válvulas GMR870 es una herramienta esencial para el control preciso del suministro de oxígeno en terapias respiratorias. Fabricado con una estructura de aluminio liviano y un interior de cobre resistente, este regulador combina ligereza y durabilidad, asegurando un rendimiento confiable y prolongado.

El regulador GMR870 para válvulas de cilindros pequeños de oxígeno tiene estructura de aluminio liviano con interior de cobre, conexión tipo yugo, manómetro tipo reloj, presión de entrada de 2200 PSI, presión de salida de 50 PSI y flujo de 0 a 15 lpm. Opera de -18 a 49 °C, es clase IIA (riesgo moderado) y cuenta con registro sanitario 2015DM-0014023.$d$,
  descripcion_larga_en = $d$The GMR870 Valve Regulator is an essential tool for precise oxygen supply control in respiratory therapies. Built with a lightweight aluminum body and a durable copper interior, this regulator combines lightness and durability, ensuring reliable and long-lasting performance.

The GMR870 regulator for small oxygen cylinder valves has a lightweight aluminium structure with copper interior, a yoke connection, a dial gauge, 2200 PSI inlet pressure, 50 PSI outlet pressure and 0 to 15 lpm flow. It operates from -18 to 49 °C, is class IIA (moderate risk) and has health registration 2015DM-0014023.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"GMD (Colombia)"},{"clave":"Referencia","grupo":"Identificación","valor":"GMR870-015"},{"clave":"Presión de entrada / salida","grupo":"Rendimiento","valor":"2200 / 50 PSI"},{"clave":"Flujo","grupo":"Rendimiento","valor":"0 - 15 lpm"},{"clave":"Estructura","grupo":"Material","valor":"Aluminio con interior de cobre"},{"clave":"Registro sanitario","grupo":"Regulatorio","valor":"2015DM-0014023; clase IIA"}]$j$::jsonb,
