UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/jpd-fr202-ft.pdf',
  descripcion_larga_es = $d$Termómetro digital infrarrojo, ideal para tomar lecturas rápidas, precisas y sin contacto a adultos, niños y objetos. Cuenta con una alarma para detección de fiebre sonora.

El termómetro digital infrarrojo JPD-FR202 toma la temperatura en la frente sin contacto en cerca de 1 segundo, a una distancia de 1 a 5 cm, con rango de 35 a 42,2 °C y exactitud de ±0,2 °C; también mide objetos (0 a 100 °C). Tiene alarma sonora de fiebre, memoria de las últimas 20 lecturas, apagado automático a los 10 segundos, pantalla HD LCD en °C/°F y cumple el estándar ASTM E1965-98.$d$,
  descripcion_larga_en = $d$Infrared digital thermometer, ideal for taking quick, precise, contactless readings for adults, children, and surfaces. Features an audible fever-detection alarm.

The JPD-FR202 infrared digital thermometer takes forehead temperature without contact in about 1 second, at a distance of 1 to 5 cm, with a range of 35 to 42.2 °C and ±0.2 °C accuracy; it also measures objects (0 to 100 °C). It has a fever sound alarm, memory of the last 20 readings, automatic shut-off after 10 seconds, an HD LCD in °C/°F and meets the ASTM E1965-98 standard.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"GMD (Colombia)"},{"clave":"Referencia","grupo":"Identificación","valor":"JPD-FR202"},{"clave":"Rango frente","grupo":"Medición","valor":"35 - 42,2 °C ±0,2 °C"},{"clave":"Rango objetos","grupo":"Medición","valor":"0 - 100 °C ±1,0 °C"},{"clave":"Distancia / tiempo","grupo":"Medición","valor":"1 - 5 cm / ≈ 1 s"},{"clave":"Memoria","grupo":"Memoria","valor":"Últimas 20 lecturas"},{"clave":"Baterías","grupo":"Energía","valor":"2 x AAA"}]$j$::jsonb,
